INSERT INTO question (id, question, subtopic_id, difficulty, question_type) VALUES
  ('d0000000-0000-0000-0000-000000001001', 'In 18th-century French society, which of the three estates bore the entire burden of paying taxes to the state?', 'c0000009-0003-0000-0000-000000000073', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001002', 'On which historic date did the citizens of Paris storm the fortress-prison of the Bastille, marking the outbreak of the French Revolution?', 'c0000009-0003-0000-0000-000000000073', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001003', 'Who authored the influential philosophical treatise ''The Spirit of the Laws'', advocating a tripartite separation of powers within government?', 'c0000009-0003-0000-0000-000000000073', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001004', 'What was the direct tax paid by the Third Estate directly to the French royal treasury called?', 'c0000009-0003-0000-0000-000000000073', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001005', 'Who was the Bourbon monarch ruling France when the revolutionary crisis erupted in 1789?', 'c0000009-0003-0000-0000-000000000073', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001006', 'On 20 June 1789, delegates of the Third Estate assembled on an indoor tennis court at Versailles and swore not to disperse until they had:', 'c0000009-0003-0000-0000-000000000073', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001007', 'What working-class Parisian radical group was known as the ''sans-culottes''?', 'c0000009-0003-0000-0000-000000000073', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001008', 'The turbulent phase between September 1793 and July 1794 under Maximilien Robespierre is historically known as the:', 'c0000009-0003-0000-0000-000000000073', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001009', 'Which mechanical execution device was introduced during the French Revolution to achieve uniform, egalitarian capital punishment?', 'c0000009-0003-0000-0000-000000000073', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001010', 'Under the French Constitution of 1791, who qualified as an ''active citizen'' entitled to vote?', 'c0000009-0003-0000-0000-000000000073', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001011', 'Name the stirring patriotic song composed by Claude Joseph Rouget de Lisle that became the French national anthem.', 'c0000009-0003-0000-0000-000000000073', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001012', 'Who was the paramount leader of the Jacobin Club who dominated the Committee of Public Safety during the Reign of Terror?', 'c0000009-0003-0000-0000-000000000073', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001013', 'In which calendar year did Napoleon Bonaparte seize supreme political power and crown himself Emperor of France?', 'c0000009-0003-0000-0000-000000000073', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001014', 'Who was the autocratic Tsar of Russia when the revolution broke out in 1917?', 'c0000009-0003-0000-0000-000000000074', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001015', 'What name is given to the massacre of unarmed striking workers marching toward the Winter Palace in Saint Petersburg on 22 January 1905?', 'c0000009-0003-0000-0000-000000000074', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001016', 'What was the elected consultative representative assembly created by Tsar Nicholas II following the 1905 Revolution called?', 'c0000009-0003-0000-0000-000000000074', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001017', 'Which Orthodox priest led the procession of industrial workers carrying a petition to the Tsar on Bloody Sunday in 1905?', 'c0000009-0003-0000-0000-000000000074', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001018', 'Who was the chief leader and theoretician of the majority radical Bolshevik faction of the Russian Social Democratic Labour Party?', 'c0000009-0003-0000-0000-000000000074', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001019', 'What were the three radical demands outlined by Vladimir Lenin upon his return from exile in his famous ''April Theses'' of 1917?', 'c0000009-0003-0000-0000-000000000074', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001020', 'Who served as President of the Petrograd Soviet and organized the armed insurrection of October 1917 as head of the Military Revolutionary Committee?', 'c0000009-0003-0000-0000-000000000074', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001021', 'During the Russian Civil War (1918-1920), which color designation was applied to the Bolshevik military forces?', 'c0000009-0003-0000-0000-000000000074', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001022', 'What was the agrarian policy initiated by Joseph Stalin in 1929 requiring peasants to pool their land and equipment into state collective farms?', 'c0000009-0003-0000-0000-000000000074', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001023', 'What was the term used in pre-revolutionary and early Soviet Russia for well-to-do, prosperous peasants who owned larger farms?', 'c0000009-0003-0000-0000-000000000074', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001024', 'Name the state security and secret police organization founded by the Bolsheviks in December 1917 under Felix Dzerzhinsky.', 'c0000009-0003-0000-0000-000000000074', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001025', 'Which international confederation of communist parties was established in Moscow in March 1919 to foster worldwide revolution?', 'c0000009-0003-0000-0000-000000000074', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001026', 'Which is the northernmost, highest, and most continuous longitudinal range of the Himalayan mountain system?', 'c0000009-0003-0000-0000-000000000075', 'Easy', 'MCQ'),
