  ('d0000000-0000-0000-0000-000000001030', 'Which terrace-like geological formation represents the older alluvium of the northern plains, characterized by calcareous nodules known as kankar?', 'c0000009-0003-0000-0000-000000000075', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001031', 'What is the highest mountain peak in Peninsular South India, located in the Anaimalai Hills of the Western Ghats?', 'c0000009-0003-0000-0000-000000000075', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001032', 'What are the crescent-shaped mobile sand dunes found extensively in the Thar Desert called?', 'c0000009-0003-0000-0000-000000000075', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001033', 'Which is the largest brackish saltwater lagoon in India, situated along the coastal plains of Odisha south of the Mahanadi delta?', 'c0000009-0003-0000-0000-000000000075', 'Easy', 'MCQ'),
