  ('d0000000-0000-0000-0000-000000001042', 'Under which specific Article of the Constitution of India is the Election Commission of India vested with the power of superintendence of elections?', 'c0000009-0003-0000-0000-000000000076', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001043', 'How many parliamentary constituencies are currently demarcated for direct election to the Lok Sabha across India?', 'c0000009-0003-0000-0000-000000000076', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001044', 'The official set of binding norms and behavioral standards enforced on political parties and candidates during election campaigns is known as the:', 'c0000009-0003-0000-0000-000000000076', 'Medium', 'MCQ'),
