  ('d0000000-0000-0000-0000-000000001046', 'Which auxiliary device connected to an EVM prints an independent paper slip enabling the voter to visually verify their cast vote for 7 seconds?', 'c0000009-0003-0000-0000-000000000076', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001047', 'What is the official comprehensive list of registered citizens eligible to vote in a constituency formally designated as?', 'c0000009-0003-0000-0000-000000000076', 'Medium', 'MCQ'),
