  ('d0000000-0000-0000-0000-000000001051', 'Which grammatical conditional structure is standardly employed to express invariant scientific truths and immutable facts?', 'c0000009-0004-0000-0000-000000000077', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001052', 'Complete the zero conditional sentence: ''If you expose iron to moist oxygen, it _____.''', 'c0000009-0004-0000-0000-000000000077', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001053', 'Select the correct first conditional form: ''If the rainfall _____ adequate this monsoon, the crop yield will be bountiful.''', 'c0000009-0004-0000-0000-000000000077', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001054', 'Complete the second conditional sentence expressing an unreal present hypothetical: ''If I _____ his direct telephone number, I would inform him instantly.''', 'c0000009-0004-0000-0000-000000000077', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001055', 'Complete the third conditional sentence referring to an impossible past condition: ''If the navigator _____ the warning beacons, the vessel would not have run aground.''', 'c0000009-0004-0000-0000-000000000077', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001056', 'Choose the subordinating conjunction equivalent to ''if not'': ''You will fail to qualify for the tournament _____ you achieve the qualifying score.''', 'c0000009-0004-0000-0000-000000000077', 'Medium', 'MCQ'),
