  ('d0000000-0000-0000-0000-000000001063', 'Rewrite the conditional using ''unless'': ''If you do not present your admission ticket, you will not be granted entry.''', 'c0000009-0004-0000-0000-000000000077', 'Hard', 'SAQ'),
